 f.reconcileResult={status:'uncertain',receipt:{transport:'browser',work_id:'SYNTHETIC-original-work'}};f.now='2026-10-20T00:01:00Z';let d=await api.runPublishingTick(OWNER,f.adapter);assert.equal(d.summary.uncertain,4);
 // Neither a different work ID nor an unconfirmed state may release ambiguity.
