 f.reconcileResult={status:'published',external_post_id:'SYNTHETIC-post',published_at:'2026-10-20T08:00+08:00',published_at_precision:'minute',receipt:{transport:'browser',work_id:'SYNTHETIC-original-work'}};f.now='2026-10-20T00:04:00Z';d=await api.runPublishingTick(OWNER,f.adapter);assert.equal(d.summary.uncertain,0);assert.ok(d.publications.every(p=>p.status==='published'&&p.published_at_precision==='minute'));assert.equal(f.count('publishing_collections'),8);assert.equal(f.publishCalls.length,4);
