test('durable in-window observations survive a later tick while unobserved due targets continue best-effort collection',async t=>{
 const f=fixture(t);f.add('one');await f.enable();f.now='2026-10-20T00:00:20Z';await api.runPublishingTick(OWNER,f.adapter);const before=f.production();
 f.collectResult={status:'pending'};f.now='2026-10-21T00:00:20Z';await api.runPublishingTick(OWNER,f.adapter);assert.equal(f.collectionCalls.length,4);
 const savedInput=f.collectionCalls[0];f.adapter.readCollectionResult=async input=>input.post_id===savedInput.post_id?{status:'collected',observed_at:'2026-10-21T01:59:20Z',metrics:{plays:0,likes:null}}:null;
 f.now='2026-10-21T02:01:00Z';let d=await api.runPublishingTick(OWNER,f.adapter);const targets=d.collections.filter(c=>c.target_hours===24);assert.equal(targets.filter(c=>c.status==='collected').length,1);assert.equal(targets.filter(c=>c.status==='pending').length,3);const saved=targets.find(c=>c.status==='collected');assert.equal(saved.observed_at,'2026-10-21T01:59:20.000Z');assert.equal(saved.metrics.plays,0);assert.equal(saved.metrics.likes,null);assert.equal(f.collectionCalls.length,7,'other overdue targets remain eligible for actual delayed observations');assert.equal(f.production(),before);
});

test('collection-only maintenance at 11:30 keeps all publication state frozen and consumes only due metric receipts',async t=>{
 const f=fixture(t);f.add('one');await f.enable();f.now='2026-10-20T00:00:20Z';await api.runPublishingTick(OWNER,f.adapter);
 // A real earlier publication anchors this target; the test clock is injected only at the adapter boundary.
 f.sql.prepare("UPDATE publishing_posts SET published_at='2026-10-20T03:30:00.000Z'").run();f.sql.prepare("UPDATE publishing_collections SET due_at=CASE target_hours WHEN 24 THEN '2026-10-21T03:30:00.000Z' ELSE '2026-10-22T03:30:00.000Z' END").run();
 const posts=f.sql.prepare('SELECT id FROM publishing_posts ORDER BY id').all();for(const [i,status] of ['pending','submitted','uncertain','dispatching'].entries())f.sql.prepare('UPDATE publishing_posts SET status=?,lease_hash=?,lease_until=? WHERE id=?').run(status,'SYNTHETIC-publication-lease',1,posts[i].id);
 f.add('new-ready-but-unsynced','2026-10-20T02:00:00Z');f.adapter.publish=async()=>{throw Error('collection tick must never publish')};f.adapter.reconcile=async()=>{throw Error('collection tick must never reconcile publication')};
 const protectedState=()=>JSON.stringify(['publishing_plans','publishing_authorizations','publishing_reserve','publishing_slots','publishing_posts'].map(table=>f.sql.prepare('SELECT * FROM '+table+' ORDER BY rowid').all())),before=protectedState(),production=f.production();
 f.now='2026-10-21T03:29:59Z';await api.runCollectionTick(OWNER,f.adapter);assert.equal(f.collectionCalls.length,0);assert.equal(protectedState(),before);
 f.now='2026-10-21T03:30:00Z';f.collectResult={status:'pending',reason:'SYNTHETIC waiting for real browser evidence'};await api.runCollectionTick(OWNER,f.adapter);assert.equal(f.collectionCalls.length,4);assert.equal(f.sql.prepare("SELECT count(*) n FROM publishing_collections WHERE target_hours=24 AND status='pending' AND metrics IS NULL").get().n,4);
 const saved=f.collectionCalls[0];f.adapter.readCollectionResult=async input=>input.post_id===saved.post_id?{status:'collected',observed_at:'2026-10-21T05:29:59Z',metrics:{plays:0,likes:null},source:{kind:'SYNTHETIC-durable-metric-receipt'}}:null;
 f.now='2026-10-21T05:30:01Z';await api.runCollectionTick(OWNER,f.adapter);const rows=f.sql.prepare('SELECT * FROM publishing_collections WHERE target_hours=24').all();assert.equal(rows.filter(c=>c.status==='collected').length,1);assert.equal(rows.filter(c=>c.status==='pending').length,3);assert.equal(JSON.parse(rows.find(c=>c.status==='collected').metrics).plays,0);assert.equal(f.collectionCalls.length,7,'late receipt ingestion preserves outstanding observation work without publication changes');assert.equal(protectedState(),before);assert.equal(f.production(),production);assert.equal(f.count('publishing_reserve'),1,'newly approved production must not be synced');
});

