// A copy approval survives an expired transport lease only within the exact,
// still-live GLM grant. Fresh claims never create a new copy approval.
async function glmReclaimedAmendment(t){const f=await glmContinuationFixture(t);await glmApi.authorizeSlotContinuation(OWNER,f.glmArgs);const ks=f.glmWorks.find(x=>x.input.platform==='kuaishou'),first=await glmApi.claimBrowserPublishingWork(OWNER,{work_id:ks.work.id,worker:'SYNTHETIC-first-tag-owner'}),base=await glmApi.readPublishingDispatchMaterials(OWNER,ks.input),args={request_id:'SYNTHETIC-immutable-GLM-topics',work_id:ks.work.id,claim_token:first.claim_token,base_materials_hash:base.materials_hash,old_tags:base.copy.tags,new_tags:['怎么用好AI','GLMLegal','合同审查','官方演示解读'],authorization_reference:'SYNTHETIC owner approved these exact four tags once'};await glmApi.authorizeScheduledBrowserTagAmendment(OWNER,args);const amendmentKey='publishing_scheduled_tag_amendment_v1:'+OWNER+':'+ks.input.idempotency_key,amendmentRaw=f.sql.prepare('SELECT value FROM app_state WHERE key=?').get(amendmentKey).value,amended=await glmApi.readPublishingDispatchMaterials(OWNER,ks.input);t.mock.timers.setTime(Date.parse(f.now)+11*60000);const fresh=await glmApi.claimBrowserPublishingWork(OWNER,{work_id:ks.work.id,worker:'SYNTHETIC-fresh-original-work'});return{...f,ks,first,fresh,args,base,amended,amendmentKey,amendmentRaw};}
