test('fresh GLM same-work claim inherits immutable four-topic approval while latest token and both actual form checks remain required',async t=>{const f=await glmReclaimedAmendment(t),packet=await glmApi.readPublishingDispatchMaterials(OWNER,f.ks.input);assert.equal(packet.materials_hash,f.amended.materials_hash);assert.deepEqual(packet.copy.tags,f.args.new_tags);assert.equal(packet.copy.title,f.base.copy.title);assert.equal(packet.copy.description,f.base.copy.description);assert.equal(f.sql.prepare('SELECT value FROM app_state WHERE key=?').get(f.amendmentKey).value,f.amendmentRaw);const stored=JSON.parse(f.amendmentRaw),work=JSON.parse(f.sql.prepare('SELECT value FROM app_state WHERE key=?').get(f.ks.key).value);assert.notEqual(work.claim_hash,stored.claim_hash);assert.equal(stored.claim_hash,createHash('sha256').update(f.first.claim_token).digest('hex'));assert.equal((await glmApi.authorizeScheduledBrowserTagAmendment(OWNER,{...f.args,claim_token:f.fresh.claim_token})).replayed,true);assert.equal(f.sql.prepare('SELECT value FROM app_state WHERE key=?').get(f.amendmentKey).value,f.amendmentRaw);const checkpoint={work_id:f.ks.work.id,claim_token:f.fresh.claim_token,account_id:f.ks.input.account_id,local_sha256:f.glm.video_sha256};await assert.rejects(()=>glmApi.checkpointBrowserPublishingWork(OWNER,{...checkpoint,claim_token:f.first.claim_token,phase:'ready_to_submit',preflight:glmForm(packet,f.ks.input)}),/凭据已失效/);await assert.rejects(()=>glmApi.checkpointBrowserPublishingWork(OWNER,{...checkpoint,phase:'ready_to_submit'}),/完整表单/);await assert.rejects(()=>glmApi.checkpointBrowserPublishingWork(OWNER,{...checkpoint,phase:'ready_to_submit',preflight:glmForm(f.base,f.ks.input)}));await glmApi.checkpointBrowserPublishingWork(OWNER,{...checkpoint,phase:'ready_to_submit',preflight:glmForm(packet,f.ks.input)});await assert.rejects(()=>glmApi.checkpointBrowserPublishingWork(OWNER,{...checkpoint,phase:'submitting'}),/完整表单/);await glmApi.checkpointBrowserPublishingWork(OWNER,{...checkpoint,phase:'submitting',preflight:glmForm(packet,f.ks.input)});assert.equal(JSON.parse(f.sql.prepare('SELECT value FROM app_state WHERE key=?').get(f.ks.key).value).state,'submitting');assert.equal(f.count('publishing_posts'),4);assert.equal(f.publishCalls.length,0);assert.equal(f.count('publishing_collections'),0);});
test('reclaimed tag approval never authorizes another work, new copy/topics, expired grant, reconciliation or unknown/submitted result',async t=>{for(const kind of ['work-id','input-hash','input-body','new-tags','copy-body','grant-work-id','grant-expired','old-lease-unexpired','bad-claim-date','claim-expired','reconcile','submitting','submitted','uncertain','result'])await t.test(kind,async t=>{const f=await glmReclaimedAmendment(t),w=JSON.parse(f.sql.prepare('SELECT value FROM app_state WHERE key=?').get(f.ks.key).value);if(kind==='work-id')w.id='pbw_SYNTHETIC-other';if(kind==='input-hash')w.input_hash='9'.repeat(64);if(kind==='input-body')w.input.title='SYNTHETIC other work body';if(kind==='copy-body')f.glmReview.platforms.kuaishou.description+='SYNTHETIC unauthorized change';if(kind==='reconcile')w.claim_kind='reconcile';if(['submitting','submitted','uncertain'].includes(kind)){w.state=kind;w.phase=kind;}if(kind==='result')w.result={status:'submitted'};if(kind==='claim-expired')w.lease_until=Date.now()-1;if(kind==='bad-claim-date')w.updated_at='not-a-timestamp';f.sql.prepare('UPDATE app_state SET value=? WHERE key=?').run(JSON.stringify(w),f.ks.key);if(['new-tags','old-lease-unexpired'].includes(kind)){const a=JSON.parse(f.amendmentRaw);if(kind==='new-tags')a.new_tags=['怎么用好AI','GLMLegal','合同审查','AI怎么用'];else a.claim_lease_until=Date.now()+60000;f.sql.prepare('UPDATE app_state SET value=? WHERE key=?').run(JSON.stringify(a),f.amendmentKey);}if(kind==='grant-work-id'){const row=f.sql.prepare("SELECT key,value FROM app_state WHERE key LIKE 'publishing_slot_continuation_v1:%'").get(),g=JSON.parse(row.value);g.work_ids=g.work_ids.filter(id=>id!==f.ks.work.id);f.sql.prepare('UPDATE app_state SET value=? WHERE key=?').run(JSON.stringify(g),row.key);}if(kind==='grant-expired')t.mock.timers.setTime(Date.parse(f.now)+3600000);await assert.rejects(()=>glmApi.readPublishingDispatchMaterials(OWNER,f.ks.input));assert.equal(f.publishCalls.length,0);assert.equal(f.count('publishing_collections'),0);if(!['new-tags','old-lease-unexpired'].includes(kind))assert.equal(f.sql.prepare('SELECT value FROM app_state WHERE key=?').get(f.amendmentKey).value,f.amendmentRaw);});});


