const v5PublishingOutros=JSON.parse(fs.readFileSync('production/outro-v5-assets.json','utf8'));
function tagPublishingCategory(f,job,time,{legacy=false,unknownTail=false}={}){
 const m=job.milestones.find(m=>m.node==='video'),a=JSON.parse(m.artifact);
 a.qa.outro_sha256=unknownTail?'SYNTHETIC-historical-unclassified-tail':v5PublishingOutros.variants[time==='08:00'?'dark':'light'].sha256;
 if(!legacy)a.qa.template_publishing_slot={schema:'template-publishing-slot-v1',timezone:'Asia/Shanghai',time,selection_sequence:time==='08:00'?1:2,policy:'morning-light-evening-dark-v1'};
 m.artifact=JSON.stringify(a);m.artifact_hash=createHash('sha256').update(m.artifact).digest('hex');f.sql.prepare('UPDATE production_milestones SET artifact=?,artifact_hash=? WHERE id=?').run(m.artifact,m.artifact_hash,m.id);
}
async function classifiedPreparationFixture(t,time){
 const f=fixture(t),opposite=time==='08:00'?'18:00':'08:00';
 tagPublishingCategory(f,f.add('SYNTHETIC-opposite-older','2026-10-19T10:00:00Z'),opposite);
 tagPublishingCategory(f,f.add('SYNTHETIC-matching-first','2026-10-19T11:00:00Z'),time);
 tagPublishingCategory(f,f.add('SYNTHETIC-matching-later','2026-10-19T12:00:00Z'),time);
 await f.enable();f.now=time==='08:00'?'2026-10-19T23:00:00.000Z':'2026-10-20T09:00:00.000Z';t.mock.timers.enable({apis:['Date'],now:Date.parse(f.now)});
 for(const platform of ['douyin','bilibili','kuaishou'])f.sql.prepare('INSERT INTO app_state(key,value) VALUES (?,?)').run('publishing_browser_account_v2:'+OWNER+':'+platform,JSON.stringify({platform,state:'ready',account_id:'account-'+platform,can_publish:true,can_collect:true,observed_at:f.now}));
 f.prepared=await api.prepareNextPublishingSlot(OWNER,f.adapter);
 const work=f.prepared.work.find(w=>w.platform==='douyin'),claim=await api.claimPublishingPreparation(OWNER,{work_id:work.id,worker:'SYNTHETIC category draft preparer'}),packet=await api.readPublishingPreparationMaterials(OWNER,{work_id:work.id}),preflight=preparationObservation(packet,f.now);preflight.evidence_url='https://creator.douyin.com/creator-micro/content/upload';
 await api.checkpointPublishingPreparation(OWNER,{work_id:work.id,claim_token:claim.claim_token,phase:'draft_saved',account_id:packet.account_id,account_label:'SYNTHETIC current author',video_sha256:packet.video_sha256,materials_hash:packet.materials_hash,evidence_url:preflight.evidence_url,evidence_note:'SYNTHETIC saved original frozen category draft',draft_locator:'SYNTHETIC original category draft',preflight});
 f.due=time==='08:00'?'2026-10-20T00:00:00.000Z':'2026-10-20T10:00:00.000Z';return f;
}
